// Accept a bare domain, a full URL, or an email address, and hand back a clean hostname.
// Callers send all three and a lookup that only accepts one shape gets abandoned.
const raw = $json.body ?? $json;
let v = String(raw.domain || raw.url || raw.email || '').trim().toLowerCase();
if (!v) throw new Error('Send a JSON body with a "domain", "url" or "email" field.');
if (v.includes('@')) v = v.split('@').pop();
v = v.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0].split(':')[0];
if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(v)) throw new Error('"' + v + '" does not look like a domain.');
return [{ json: { domain: v, askedAt: new Date().toISOString() } }];

// This is what the caller receives, so it is a contract: same keys every time, nulls rather than
// missing fields, and one 'ok' flag they can branch on without inspecting the shape.
const r = $input.first()?.json || {};
const mx = Array.isArray(r.mxRecords) ? r.mxRecords : [];
const host = (mx[0] && (mx[0].exchange || mx[0])) || '';
const provider = /google|gmail/i.test(host) ? 'Google Workspace'
  : /outlook|microsoft|protection\.outlook/i.test(host) ? 'Microsoft 365'
  : /zoho/i.test(host) ? 'Zoho' : /proton/i.test(host) ? 'Proton' : host ? 'other' : null;

return [{
  json: {
    ok: !!r.domain,
    domain: r.domain || $('Read the domain').first().json.domain,
    resolves: r.mxFound === true || (Array.isArray(r.addresses) && r.addresses.length > 0) || null,
    accepts_mail: mx.length > 0 || null,
    mail_provider: provider,
    mx_hosts: mx.map((m) => m.exchange || m).slice(0, 4),
    is_free_provider: r.isFreeProvider ?? null,
    checked_at: new Date().toISOString(),
  },
}];
